cublasStatus_t cublasGetVersion_v2(cublasHandle_t handle, int * version) {
    // TraceCall("cublasGetVersion");
    if (version == NULL) return CUBLAS_STATUS_INVALID_VALUE;
    *version = CUBLAS_VERSION;
    return CUBLAS_STATUS_SUCCESS;
}

global_custom_code.pre_wrapper_call:
bool needProfile = g_profileHandler.isCallbackEnabled != NULL &&
    g_profileHandler.isCallbackEnabled(g_profileDomain, cublas_TRACE_CBID_$WRAPPER_FUNC_NAME) != 0;
if (needProfile) {
    g_profileHandler.profileCallbackBegin(g_profileDomain, cublas_TRACE_CBID_$WRAPPER_FUNC_NAME);
}
